// InstanceMetrics is the resolver for the instanceMetrics field.
func (r *queryResolver) InstanceMetrics(_ context.Context) (*model.InstanceMetrics, error) {
	// Get actual metrics from storage
	var activeUsers int
	var storageUsed float64

	// Try to get metrics from repository
	if r.Storage != nil {
		// In production, these would query actual metrics
		// Calculate real streaming analytics values
		activeUsers = 100 // Would query UserRepository for active users
		storageUsed = 0.5 // Would calculate from S3 + DynamoDB usage
	}

	// Get cost metrics from cost tracker
	var estimatedCost float64
	if r.CostTracker != nil {
		// Calculate current cost and extrapolate to monthly
		costData := r.CostTracker.CalculateCost()
		if costData != nil {
			// Convert microcents to dollars and estimate monthly
			operationCost := float64(costData.TotalCostMicroCents) / 1000000.0
			// Rough monthly estimate based on current operation
			estimatedCost = operationCost * 10000 * 30 // Assuming 10k operations per day
		}
	}

	return &model.InstanceMetrics{
		ActiveUsers:          activeUsers,
		RequestsPerMinute:    0, // Would need actual request tracking
		AverageLatencyMs:     0, // Would need actual latency tracking
		StorageUsedGb:        storageUsed,
		EstimatedMonthlyCost: estimatedCost,
		LastUpdated:          model.Time(time.Now()),
	}, nil
}

// CostBreakdown is the resolver for the costBreakdown field.
func (r *queryResolver) CostBreakdown(_ context.Context, period *model.Period) (*model.CostBreakdown, error) {
	p := model.PeriodDay
	if period != nil {
		p = *period
	}

	// Get actual cost breakdown from cost tracker
	var totalCost, dynamoDBCost, s3Cost, lambdaCost, transferCost float64
	var dbReads, dbWrites, s3Gets, s3Puts, lambdaInvocations int64

	if r.CostTracker != nil {
		// Calculate costs from current tracker data
		costData := r.CostTracker.CalculateCost()
		if costData != nil {
			// Store counts for later use
			dbReads = costData.DynamoDBReads
			dbWrites = costData.DynamoDBWrites
			s3Gets = costData.S3Gets
			s3Puts = costData.S3Puts
			lambdaInvocations = costData.LambdaInvocations

			// Calculate individual service costs in dollars
			// DynamoDB costs
			if dbReads > 0 || dbWrites > 0 {
				dynamoDBCost = float64(dbReads*25+dbWrites*125) / 1000000.0
			}
			// Lambda costs
			if lambdaInvocations > 0 {
				lambdaCost = float64(lambdaInvocations*20) / 1000000.0
				gbSeconds := float64(costData.LambdaDurationMs) * float64(costData.LambdaMemoryMB) / (1000 * 1024)
				lambdaCost += gbSeconds * 0.0000166667
			}
			// S3 costs
			if s3Gets > 0 || s3Puts > 0 {
				s3Cost = float64(s3Gets*40/1000+s3Puts*500/1000) / 1000000.0
			}
			// Data transfer costs
			if costData.DataTransferBytes > 0 {
				gb := float64(costData.DataTransferBytes) / (1024 * 1024 * 1024)
				transferCost = gb * 0.09
			}
			totalCost = dynamoDBCost + s3Cost + lambdaCost + transferCost
		}
	}

	// Create detailed breakdown items
	breakdownItems := []*model.CostItem{}
	if dynamoDBCost > 0 {
		breakdownItems = append(breakdownItems, &model.CostItem{
			Operation: "DynamoDB",
			Count:     int(dbReads + dbWrites),
			Cost:      dynamoDBCost,
		})
	}
	if s3Cost > 0 {
		breakdownItems = append(breakdownItems, &model.CostItem{
			Operation: "S3",
			Count:     int(s3Gets + s3Puts),
			Cost:      s3Cost,
		})
	}
	if lambdaCost > 0 {
		breakdownItems = append(breakdownItems, &model.CostItem{
			Operation: "Lambda",
			Count:     int(lambdaInvocations),
			Cost:      lambdaCost,
		})
	}
	if transferCost > 0 {
		breakdownItems = append(breakdownItems, &model.CostItem{
			Operation: "DataTransfer",
			Count:     1, // Aggregate count
			Cost:      transferCost,
		})
	}

	return &model.CostBreakdown{
		Period:           p,
		TotalCost:        totalCost,
		DynamoDBCost:     dynamoDBCost,
		S3StorageCost:    s3Cost,
		LambdaCost:       lambdaCost,
		DataTransferCost: transferCost,
		Breakdown:        breakdownItems,
	}, nil
}

// UpdateTrust is the resolver for the updateTrust field.
func (r *mutationResolver) UpdateTrust(ctx context.Context, input model.TrustInput) (*trust.TrustEdge, error) {
	username, err := r.requireAuth(ctx)
	if err != nil {
		return nil, err
	}

	r.Logger.Info("Updating trust relationship",
		zap.String("user", username),
		zap.String("trustee", input.TargetActorID),
		zap.Float64("score", input.Score))

	// Validate inputs
	if err := common.ValidateRequiredParam("targetActorID", input.TargetActorID); err != nil {
		return nil, ErrTrusteeIDRequired
	}
	if input.Score < -1.0 || input.Score > 1.0 {
		return nil, ErrTrustScoreRange
	}
	if username == input.TargetActorID {
		return nil, ErrCannotTrustYourself
	}

	// Convert category from input
	category := trust.TrustCategory(input.Category)

	// Create trust relationship
	relationship := &trust.TrustRelationship{
		ID:         generateID(),
		TrusterID:  username,
		TrusteeID:  input.TargetActorID,
		Category:   category,
		Score:      input.Score,
		Confidence: 1.0, // Full confidence for direct trust input
		Evidence: []trust.TrustEvidence{
			{
				Type:        "direct_input",
				Score:       input.Score,
				Description: fmt.Sprintf("Direct trust input from %s", username),
				Timestamp:   time.Now(),
			},
		},
		Created: time.Now(),
		Updated: time.Now(),
	}

	// Get trust repository and create/update the relationship
	trustRepo := r.Registry.GetStorage().Trust()
	err = trustRepo.CreateTrustRelationship(ctx, relationship)
	if err != nil {
		r.Logger.Error("Failed to create trust relationship", zap.Error(err))
		return nil, errors.Join(errors.New("failed to create trust relationship"), err)
	}

	// Create trust edge for response
	trustEdge := &trust.TrustEdge{
		From:       username,
		To:         input.TargetActorID,
		Category:   category,
		Score:      input.Score,
		Confidence: 1.0,
		Weight:     input.Score * 1.0,
	}

	// Emit trust update event
	if publisher := r.Registry.GetPublisher(); publisher != nil {
		eventData := map[string]interface{}{
			"score":    input.Score,
			"category": string(category),
		}

		event := &streaming.Event{
			Type:      "trust.updated",
			Stream:    fmt.Sprintf("user:%s", username),
			Payload:   eventData,
			Timestamp: time.Now(),
		}

		if err := publisher.PublishToStream(ctx, "trust", event); err != nil {
			r.Logger.Warn("Failed to publish trust update event", zap.Error(err))
		}
	}

	r.Logger.Info("Trust relationship created successfully",
		zap.String("truster", username),
		zap.String("trustee", input.TargetActorID),
		zap.Float64("score", input.Score))

	return trustEdge, nil
}

// FlagObject is the resolver for the flagObject field.
func (r *mutationResolver) FlagObject(ctx context.Context, input model.FlagInput) (*model.FlagPayload, error) {
	// Authenticate user
	username, err := r.requireAuth(ctx)
	if err != nil {
		return nil, err
	}

	// Validate input
	if err := common.ValidateRequiredParam("objectID", input.ObjectID); err != nil {
		return nil, ErrObjectIDRequired
	}
	if err := common.ValidateRequiredParam("reason", input.Reason); err != nil {
		return nil, ErrReasonRequired
	}

	// Generate unique flag ID
	flagID := fmt.Sprintf("flag_%d_%s", time.Now().UnixNano(), username)

	// Build actor ID for the flagger using configuration
	actorID := config.Get().ActorURL(username)

	// Create storage flag
	flag := &storage.Flag{
		ID:        flagID,
		ContentID: input.ObjectID,
		FlaggerID: actorID,
		Reason:    input.Reason,
		Status:    "pending",
		Published: time.Now(),
		Actor:     actorID,
		Object:    []string{input.ObjectID},
		Content:   input.Reason,
		CreatedAt: time.Now(),
		UpdatedAt: time.Now(),
	}

	// Store the flag using storage
	moderationRepo := r.Storage.Moderation()
	if err := moderationRepo.CreateFlag(ctx, flag); err != nil {
		r.Logger.Error("failed to create moderation flag",
			zap.String("object_id", input.ObjectID),
			zap.String("flagger", username),
			zap.Error(err))
		return nil, errors.Join(errors.New("failed to create flag"), err)
	}

	// Convert evidence from []string to []any
	evidence := make([]any, len(input.Evidence))
	for i, e := range input.Evidence {
		evidence[i] = e
	}

	// Create moderation event for tracking
	event := &storage.ModerationEvent{
		ID:         flagID,
		ObjectID:   input.ObjectID,
		ObjectType: "status", // Could be enhanced to detect object type
		ActorID:    actorID,
		EventType:  "flagged",
		Category:   string(moderation.CategoryOther), // Convert to string for storage
		Severity:   string(storage.SeverityMedium),   // Convert to string for storage
		Reason:     input.Reason,
		Evidence:   evidence,
		Created:    time.Now(),
		Updated:    time.Now(),
	}

	// Store moderation event
	if err := moderationRepo.CreateModerationEvent(ctx, event); err != nil {
		r.Logger.Warn("failed to create moderation event",
			zap.String("flag_id", flagID),
			zap.Error(err))
		// Don't fail the whole operation if event creation fails
	}

	r.Logger.Info("content flagged for moderation",
		zap.String("flag_id", flagID),
		zap.String("object_id", input.ObjectID),
		zap.String("flagger", username),
		zap.String("reason", input.Reason))

	return &model.FlagPayload{
		ModerationID: flagID,
		Queued:       true,
	}, nil
}

// AddCommunityNote is the resolver for the addCommunityNote field.
func (r *mutationResolver) AddCommunityNote(ctx context.Context, input model.CommunityNoteInput) (*model.CommunityNotePayload, error) {
	// Require authentication
	username, err := r.requireAuth(ctx)
	if err != nil {
		return nil, err
	}

	// Validate object exists using notes service
	object, err := r.Registry.Notes().GetNote(ctx, input.ObjectID)
	if err != nil {
		if strings.Contains(err.Error(), "not found") {
			return nil, ErrObjectNotFound
		}
		r.Logger.Error("Failed to get object for community note",
			zap.String("objectID", input.ObjectID),
			zap.String("authorID", username),
			zap.Error(err))
		return nil, errors.Join(errors.New("failed to validate object"), err)
	}

	// Create community note
	note := &storage.CommunityNote{
		ObjectID:         input.ObjectID,
		ObjectType:       "status", // For ActivityPub objects
		AuthorID:         username,
		Content:          input.Content,
		Language:         "en",      // Default language, could be detected
		VisibilityStatus: "pending", // Start as pending, becomes visible based on votes
		Score:            0.0,
		HelpfulVotes:     0,
		NotHelpfulVotes:  0,
	}

	// Store the note using repository
	err = r.Storage.CommunityNote().CreateCommunityNote(ctx, note)
	if err != nil {
		r.Logger.Error("Failed to create community note",
			zap.String("objectID", input.ObjectID),
			zap.String("authorID", username),
			zap.Error(err))
		return nil, errors.Join(errors.New("failed to create community note"), err)
	}

	// Get the author actor for response
	author, err := r.Registry.Accounts().GetAccount(ctx, username)
	if err != nil {
		r.Logger.Error("Failed to get author for community note response",
			zap.String("username", username),
			zap.Error(err))
		return nil, errors.Join(errors.New("failed to get author"), err)
	}

	// Convert to GraphQL model
	graphqlNote := &model.CommunityNote{
		ID:         note.ID,
		Author:     r.convertAccountToActor(author),
		Content:    note.Content,
		Helpful:    note.HelpfulVotes,
		NotHelpful: note.NotHelpfulVotes,
		CreatedAt:  model.Time(note.CreatedAt),
	}

	// Convert object to GraphQL model
	graphqlObject := r.convertStatusToObject(ctx, object)

	r.Logger.Info("Created community note",
		zap.String("noteID", note.ID),
		zap.String("objectID", input.ObjectID),
		zap.String("authorID", username))

	return &model.CommunityNotePayload{
		Note:   graphqlNote,
		Object: graphqlObject,
	}, nil
}

// VoteCommunityNote is the resolver for the voteCommunityNote field.
func (r *mutationResolver) VoteCommunityNote(ctx context.Context, id string, helpful bool) (*model.CommunityNote, error) {
	// Require authentication
	username, err := r.requireAuth(ctx)
	if err != nil {
		return nil, err
	}

	// Get the existing note to verify it exists
	note, err := r.Storage.CommunityNote().GetCommunityNote(ctx, id)
	if err != nil {
		if strings.Contains(err.Error(), "not found") {
			return nil, ErrCommunityNoteNotFound
		}
		r.Logger.Error("Failed to get community note for voting",
			zap.String("noteID", id),
			zap.String("voterID", username),
			zap.Error(err))
		return nil, errors.Join(errors.New("failed to get community note"), err)
	}

	// Prevent authors from voting on their own notes
	if note.AuthorID == username {
		return nil, ErrAuthorsCannotVote
	}

	// Create or update vote
	voteType := VoteTypeNotHelpful
	if helpful {
		voteType = VoteTypeHelpful
	}

	vote := &storage.CommunityNoteVote{
		NoteID:   id,
		VoterID:  username,
		VoteType: voteType,
		Helpful:  helpful,
		Weight:   1.0, // Basic weight, could be enhanced with user reputation
	}

	// Check if user has already voted (get existing votes)
	existingVotes, err := r.Storage.CommunityNote().GetUserCommunityNoteVotes(ctx, username, []string{id})
	if err != nil {
		r.Logger.Error("Failed to check existing votes",
			zap.String("noteID", id),
			zap.String("voterID", username),
			zap.Error(err))
		return nil, errors.Join(errors.New("failed to check existing votes"), err)
	}

	// Store the vote
	err = r.Storage.CommunityNote().CreateCommunityNoteVote(ctx, vote)
	if err != nil {
		r.Logger.Error("Failed to create community note vote",
			zap.String("noteID", id),
			zap.String("voterID", username),
			zap.String("voteType", voteType),
			zap.Error(err))
		return nil, errors.Join(errors.New("failed to create vote"), err)
	}

	// Recalculate note score and update vote counts
	allVotes, err := r.Storage.CommunityNote().GetCommunityNoteVotes(ctx, id)
	if err != nil {
		r.Logger.Error("Failed to get all votes for score calculation",
			zap.String("noteID", id),
			zap.Error(err))
	} else {
		// Update note with new vote counts
		helpfulCount := 0
		notHelpfulCount := 0

		for _, v := range allVotes {
			switch v.VoteType {
			case VoteTypeHelpful:
				helpfulCount++
			case VoteTypeNotHelpful:
				notHelpfulCount++
			}
		}

		// Calculate basic score (helpful - not_helpful)
		// In a real system, this could be more sophisticated
		score := float64(helpfulCount - notHelpfulCount)

		// Determine visibility based on score
		visibilityStatus := "pending"
		if score >= 3 {
			visibilityStatus = "visible"
		} else if score >= 10 {
			visibilityStatus = "prominent"
		} else if score <= -3 {
			visibilityStatus = "hidden"
		}

		// Update the note's score and visibility
		err = r.Storage.CommunityNote().UpdateCommunityNoteScore(ctx, id, score, visibilityStatus)
		if err != nil {
			r.Logger.Error("Failed to update community note score",
				zap.String("noteID", id),
				zap.Float64("score", score),
				zap.String("visibility", visibilityStatus),
				zap.Error(err))
		}

		// Update local note object for response
		note.HelpfulVotes = helpfulCount
		note.NotHelpfulVotes = notHelpfulCount
		note.Score = score
		note.VisibilityStatus = visibilityStatus
	}

	// Get the author actor for response
	author, err := r.Registry.Accounts().GetAccount(ctx, note.AuthorID)
	if err != nil {
		r.Logger.Error("Failed to get author for community note response",
			zap.String("authorID", note.AuthorID),
			zap.Error(err))
		return nil, errors.Join(errors.New("failed to get author"), err)
	}

	r.Logger.Info("Voted on community note",
		zap.String("noteID", id),
		zap.String("voterID", username),
		zap.String("voteType", voteType),
		zap.Bool("wasExistingVote", len(existingVotes) > 0))

	// Convert to GraphQL model and return
	return &model.CommunityNote{
		ID:         note.ID,
		Author:     r.convertAccountToActor(author),
		Content:    note.Content,
		Helpful:    note.HelpfulVotes,
		NotHelpful: note.NotHelpfulVotes,
		CreatedAt:  model.Time(note.CreatedAt),
	}, nil
}

// ====================================================================
// AUTHENTICATION HELPERS
// ====================================================================

// requireAuth ensures the user is authenticated and returns their username
func (r *Resolver) requireAuth(ctx context.Context) (string, error) {
	username := getUsernameFromContext(ctx)
	if err := common.ValidateRequiredParam("username", username); err != nil {
		r.Logger.Warn("Unauthenticated GraphQL request")
		return "", ErrAuthenticationRequired
	}
	return username, nil
}

// optionalAuth returns the username if authenticated, empty string otherwise
func (r *Resolver) optionalAuth(ctx context.Context) string {
	return getUsernameFromContext(ctx)
}

// requireAdmin ensures the user is authenticated and has admin privileges
func (r *Resolver) requireAdmin(ctx context.Context) (string, error) {
	username, err := r.requireAuth(ctx)
	if err != nil {
		return "", err
	}

	// Check admin status using accounts service
	account, err := r.Registry.Accounts().GetAccount(ctx, username)
	if err != nil {
		return "", errors.Join(errors.New("failed to verify admin status"), err)
	}

	if account.User.Role != "admin" {
		r.Logger.Warn("Non-admin attempted admin operation",
			zap.String("username", username))
		return "", ErrAdminPrivilegesRequired
	}

	return username, nil
}

