// convertNotificationToGraphQL converts a service notification to GraphQL type
func (r *Resolver) convertNotificationToGraphQL(ctx context.Context, notif *models.Notification) *model.Notification {
	if notif == nil {
		return nil
	}

	// Get account that triggered the notification
	var account *activitypub.Actor
	if notif.ActorID != "" {
		result, err := r.Registry.Accounts().GetAccount(ctx, notif.ActorID)
		if err == nil && result != nil {
			account = r.convertAccountToActor(result)
		}
	}

	// Get related status if applicable
	var status *model.Object
	if notif.TargetID != "" {
		result, err := r.Registry.Notes().GetNote(ctx, notif.TargetID)
		if err == nil && result != nil {
			status = r.convertStatusToObject(ctx, result)
		}
	}

	return &model.Notification{
		ID:        notif.ID,
		Type:      notif.Type,
		Account:   account,
		Status:    status,
		Read:      notif.IsRead,
		CreatedAt: model.Time(notif.CreatedAt),
	}
}

// Include all converter functions (from service_converters.go)
// These need to be methods on Resolver to access Registry

func (r *Resolver) convertConversationToGraphQL(ctx context.Context, conv *models.Conversation) *model.Conversation {
	if conv == nil {
		return nil
	}

	// Convert participant IDs to actors
	accounts := make([]*activitypub.Actor, 0, len(conv.Participants))
	for _, participantID := range conv.Participants {
		result, err := r.Registry.Accounts().GetAccount(ctx, participantID)
		if err == nil && result != nil {
			accounts = append(accounts, r.convertAccountToActor(result))
		}
	}

	var lastStatus *model.Object
	if conv.LastStatusID != "" {
		result, err := r.Registry.Notes().GetNote(ctx, conv.LastStatusID)
		if err == nil && result != nil {
			lastStatus = r.convertStatusToObject(ctx, result)
		}
	}

	return &model.Conversation{
		ID:         conv.ID,
		LastStatus: lastStatus,
		Unread:     conv.Unread,
		Accounts:   accounts,
		CreatedAt:  model.Time(conv.CreatedAt),
		UpdatedAt:  model.Time(conv.UpdatedAt),
	}
}

func (r *Resolver) convertListToGraphQL(ctx context.Context, list *models.List) *model.List {
	if list == nil {
		return nil
	}

	repliesPolicy := model.RepliesPolicyList
	switch strings.ToUpper(list.RepliesPolicy) {
	case "FOLLOWED":
		repliesPolicy = model.RepliesPolicyFollowed
	case "NONE":
		repliesPolicy = model.RepliesPolicyNone
	}

	accountCount := 0
	accounts := []*activitypub.Actor{}

	if list.ID != "" {
		result, err := r.Registry.Lists().GetListMembers(ctx, &lists.GetListMembersQuery{
			ViewerID: getUsernameFromContext(ctx),
			ListID:   list.ID,
		})
		if err == nil {
			accountCount = len(result.Members)
			for _, member := range result.Members {
				accounts = append(accounts, r.convertAccountToActor(member))
			}
		}
	}

	return &model.List{
		ID:            list.ID,
		Title:         list.Title,
		RepliesPolicy: repliesPolicy,
		Exclusive:     list.Exclusive,
		AccountCount:  accountCount,
		Accounts:      accounts,
		CreatedAt:     model.Time(list.CreatedAt),
		UpdatedAt:     model.Time(list.UpdatedAt),
	}
}

func (r *Resolver) convertMediaToGraphQL(media *models.Media) *model.Media {
	if media == nil {
		return nil
	}

	mediaType := model.MediaTypeUnknown
	if strings.HasPrefix(media.ContentType, "image/") {
		mediaType = model.MediaTypeImage
	} else if strings.HasPrefix(media.ContentType, "video/") {
		mediaType = model.MediaTypeVideo
	} else if strings.HasPrefix(media.ContentType, "audio/") {
		mediaType = model.MediaTypeAudio
	}

	var uploadedBy *activitypub.Actor
	if media.UserID != "" {
		result, err := r.Registry.Accounts().GetAccount(context.Background(), media.UserID)
		if err == nil && result != nil {
			uploadedBy = r.convertAccountToActor(result)
		}
	}

	m := &model.Media{
		ID:          media.MediaID,
		Type:        mediaType,
		URL:         media.CDNUrl,
		PreviewURL:  &media.CDNUrl, // Could generate a thumbnail URL
		Description: &media.Description,
		Blurhash:    &media.Blurhash,
		Size:        int(media.FileSize),
		MimeType:    media.ContentType,
		CreatedAt:   model.Time(media.CreatedAt),
	}

	if media.Width > 0 {
		m.Width = &media.Width
	}
	if media.Height > 0 {
		m.Height = &media.Height
	}
	if media.Duration > 0 {
		duration := float64(media.Duration)
		m.Duration = &duration
	}
	if uploadedBy != nil {
		m.UploadedBy = uploadedBy
	}

	return m
}

func (r *Resolver) convertEmojiToGraphQL(emoji *storage.CustomEmoji) *model.CustomEmoji {
	if emoji == nil {
		return nil
	}

	return &model.CustomEmoji{
		ID:              emoji.Shortcode, // Use shortcode as ID
		Shortcode:       emoji.Shortcode,
		URL:             emoji.URL,
		StaticURL:       emoji.StaticURL,
		VisibleInPicker: emoji.VisibleInPicker,
		Category:        &emoji.Category,
		Domain:          &emoji.Domain,
		CreatedAt:       model.Time(emoji.ImageUpdatedAt),
		UpdatedAt:       model.Time(emoji.ImageUpdatedAt),
	}
}

func (r *Resolver) convertScheduledStatusToGraphQL(ctx context.Context, ss *storage.ScheduledStatus) *model.ScheduledStatus {
	if ss == nil {
		return nil
	}

	visibility := model.VisibilityPublic
	switch strings.ToLower(ss.Visibility) {
	case VisibilityUnlisted:
		visibility = model.VisibilityUnlisted
	case EventTypeFollowers, VisibilityPrivate:
		visibility = model.VisibilityFollowers
	case TimelineTypeDirect:
		visibility = model.VisibilityDirect
	}

	params := &model.StatusParams{
		Text:        ss.Status,
		Visibility:  visibility,
		Sensitive:   ss.Sensitive,
		SpoilerText: &ss.SpoilerText,
		InReplyToID: &ss.InReplyToID,
		Language:    &ss.Language,
	}

	// Handle poll if present
	if ss.Poll != nil {
		// Validate poll parameters using centralized validation
		if err := common.ValidatePollParams(ss.Poll); err != nil {
			// Log error but continue - this is a conversion function
			r.Logger.Warn("invalid poll parameters in scheduled status", zap.Error(err))
		}

		// Poll is stored as map[string]any, need to extract fields
		pollParams := &model.PollParams{}
		if options, ok := ss.Poll["options"].([]string); ok {
			pollParams.Options = options
		}
		if expiresIn, ok := ss.Poll["expires_in"].(int); ok {
			pollParams.ExpiresIn = expiresIn
		}
		if multiple, ok := ss.Poll["multiple"].(bool); ok {
			pollParams.Multiple = &multiple
		}
		if hideTotals, ok := ss.Poll["hide_totals"].(bool); ok {
			pollParams.HideTotals = &hideTotals
		}
		params.Poll = pollParams
	}

	mediaAttachments := make([]*model.Media, 0)
	for _, mediaID := range ss.MediaIDs {
		result, err := r.Registry.Media().GetMedia(ctx, &media.GetMediaQuery{
			MediaID:  mediaID,
			ViewerID: getUsernameFromContext(ctx),
		})
		if err == nil && result != nil {
			mediaAttachments = append(mediaAttachments, r.convertMediaToGraphQL(result))
		}
	}

	return &model.ScheduledStatus{
		ID:               ss.ID,
		ScheduledAt:      model.Time(ss.ScheduledAt),
		Params:           params,
		MediaAttachments: mediaAttachments,
		CreatedAt:        model.Time(ss.CreatedAt),
	}
}

func (r *Resolver) convertRelationshipToGraphQL(rel *relationships.RelationshipData) *model.Relationship {
	if rel == nil {
		return &model.Relationship{
			ID:                  "",
			Following:           false,
			FollowedBy:          false,
			Blocking:            false,
			BlockedBy:           false,
			Muting:              false,
			MutingNotifications: false,
			Requested:           false,
			DomainBlocking:      false,
			ShowingReblogs:      true,
			Notifying:           false,
		}
	}

	return &model.Relationship{
		ID:                  rel.ID,
		Following:           rel.Following,
		FollowedBy:          rel.FollowedBy,
		Blocking:            rel.Blocking,
		BlockedBy:           rel.BlockedBy,
		Muting:              rel.Muting,
		MutingNotifications: rel.MutingNotifications,
		Requested:           rel.Requested,
		DomainBlocking:      rel.DomainBlocking,
		ShowingReblogs:      rel.ShowingReblogs,
		Notifying:           rel.Notifying,
		Languages:           rel.Languages,
		Note:                &rel.Note,
	}
}

func (r *Resolver) convertAccountToActor(account *storage.Account) *activitypub.Actor {
	if account == nil || account.User == nil {
		return nil
	}
	user := account.User

	actor := &activitypub.Actor{
		BaseObject: activitypub.BaseObject{
			ID:        user.ID,
			Type:      activitypub.PersonType,
			Published: &user.CreatedAt,
			Updated:   &user.UpdatedAt,
		},
		PreferredUsername:         user.Username,
		Name:                      user.DisplayName,
		Summary:                   user.Note,
		URL:                       user.URL,
		Inbox:                     fmt.Sprintf("%s/inbox", user.URL),
		Outbox:                    fmt.Sprintf("%s/outbox", user.URL),
		Followers:                 fmt.Sprintf("%s/followers", user.URL),
		Following:                 fmt.Sprintf("%s/following", user.URL),
		PublicKey:                 nil,
		Endpoints:                 nil,
		ManuallyApprovesFollowers: user.Locked,
		Discoverable:              user.Discoverable,
	}

	// Set icon if avatar URL exists
	if user.Avatar != "" {
		actor.Icon = &activitypub.Image{
			BaseObject: activitypub.BaseObject{
				Type: "Image",
			},
			URL: user.Avatar,
		}
	}

	// Set image if header URL exists
	if user.Header != "" {
		actor.Image = &activitypub.Image{
			BaseObject: activitypub.BaseObject{
				Type: "Image",
			},
			URL: user.Header,
		}
	}

	actor.PreferredUsername = user.Username

	if err := common.ValidateSliceNotEmpty("fields", user.Fields); err == nil {
		attachments := make([]activitypub.Attachment, len(user.Fields))
		for i, field := range user.Fields {
			attachments[i] = activitypub.Attachment{
				Type:  "PropertyValue",
				Name:  field["name"],
				Value: field["value"],
			}
		}
		actor.Attachment = attachments
	}

	return actor
}

func (r *Resolver) convertNoteToObject(ctx context.Context, note *activitypub.Note) *model.Object {
	if note == nil {
		return nil
	}

	objectType := model.ObjectTypeNote
	visibility := model.VisibilityPublic

	// Determine visibility from note properties
	if note.Visibility != "" {
		switch note.Visibility {
		case VisibilityUnlisted:
			visibility = model.VisibilityUnlisted
		case VisibilityPrivate, EventTypeFollowers:
			visibility = model.VisibilityFollowers
		case TimelineTypeDirect:
			visibility = model.VisibilityDirect
		}
	}

	// Get actor information
	var actor *activitypub.Actor
	if note.AttributedTo != "" {
		// Extract username from actor ID
		parts := strings.Split(note.AttributedTo, "/")
		username := parts[len(parts)-1]
		if username != "" {
			result, err := r.Registry.Accounts().GetAccount(ctx, username)
			if err == nil && result != nil {
				actor = r.convertAccountToActor(result)
			}
		}
	}

	// Convert attachments
	attachments := make([]*activitypub.Attachment, len(note.Attachment))
	for i, att := range note.Attachment {
		attachments[i] = &att
	}

	// Convert tags
	tags := make([]*activitypub.Tag, len(note.Tag))
	for i, tag := range note.Tag {
		tags[i] = &tag
	}

	// Create inReplyTo object if exists
	var inReplyToObj *model.Object
	if note.InReplyTo != "" {
		// Fetch the actual reply object using Notes service
		replyNote, err := r.Registry.Notes().GetNote(ctx, note.InReplyTo)
		if err != nil {
			r.Logger.Debug("failed to fetch reply object",
				zap.String("reply_id", note.InReplyTo),
				zap.Error(err))
			// Continue without reply object instead of failing
			inReplyToObj = nil
		} else if replyNote != nil {
			// Convert the reply status directly to model.Object
			inReplyToObj = r.convertStatusToObject(ctx, replyNote)
		}
	}

	return &model.Object{
		ID:             note.ID,
		Type:           objectType,
		Actor:          actor,
		Content:        note.Content,
		ContentMap:     r.extractContentMaps(note.Content), // Enhanced: extract content maps with language detection
		InReplyTo:      inReplyToObj,
		Visibility:     visibility,
		Sensitive:      note.Sensitive,
		SpoilerText:    &note.Summary, // Map Summary to SpoilerText
		Attachments:    attachments,
		Tags:           tags,
		Mentions:       r.extractMentionsFromNote(note), // Enhanced: extract mentions from note tags
		CreatedAt:      model.Time(*note.Published),
		UpdatedAt:      model.Time(*note.Updated),
		RepliesCount:   r.getReplyCount(ctx, note.ID), // Use efficient count method
		LikesCount:     0,
		SharesCount:    0,
		EstimatedCost:  0,
		CommunityNotes: r.getCommunityNotesForObject(ctx, note.ID),
	}
}

// getCommunityNotesForObject efficiently gets community notes for an object
func (r *Resolver) getCommunityNotesForObject(ctx context.Context, objectID string) []*model.CommunityNote {
	notes, err := r.Storage.CommunityNote().GetVisibleCommunityNotes(ctx, objectID)
	if err != nil {
		r.Logger.Error("failed to get community notes", zap.String("objectID", objectID), zap.Error(err))
		return []*model.CommunityNote{} // Return empty on error rather than failing the request
	}

	// Convert storage.CommunityNote to model.CommunityNote
	result := make([]*model.CommunityNote, len(notes))
	for i, note := range notes {
		// Get author information - would typically fetch from Actor repository
		var author *activitypub.Actor
		if note.AuthorID != "" {
			// For now, create a minimal actor - in production you'd fetch from storage
			author = &activitypub.Actor{
				BaseObject: activitypub.BaseObject{
					ID:   note.AuthorID,
					Type: "Person",
				},
				PreferredUsername: note.AuthorID, // Simplified - would extract username properly
			}
		}

		result[i] = &model.CommunityNote{
			ID:         note.ID,
			Author:     author,
			Content:    note.Content,
			Helpful:    note.HelpfulVotes,
			NotHelpful: note.NotHelpfulVotes,
			CreatedAt:  model.Time(note.CreatedAt),
		}
	}
	return result
}

// getReplyCount efficiently gets the reply count for a note/status
func (r *Resolver) getReplyCount(ctx context.Context, noteID string) int {
	count, err := r.Storage.Status().CountReplies(ctx, noteID)
	if err != nil {
		r.Logger.Error("failed to get reply count", zap.String("noteID", noteID), zap.Error(err))
		return 0 // Return 0 on error rather than failing the request
	}
	return count
}

// extractContentMaps creates ContentMap entries for content with language detection
func (r *Resolver) extractContentMaps(content string) []*model.ContentMap {
	if err := common.ValidateRequiredParam("content", content); err != nil {
		return []*model.ContentMap{}
	}

	// Detect language using simple heuristics (similar to activity processor)
	language := r.detectContentLanguage(content)

	return []*model.ContentMap{
		{
			Language: language,
			Content:  content,
		},
	}
}

// detectContentLanguage performs simple language detection on content
func (r *Resolver) detectContentLanguage(content string) string {
	if err := common.ValidateRequiredParam("content", content); err != nil {
		return "en" // Default to English
	}

	// Convert to lowercase for analysis
	text := strings.ToLower(content)

	// Strip HTML tags for cleaner analysis
	text = r.stripHTMLTags(text)

	// Character-based detection for non-Latin scripts
	if r.hasJapaneseCharacters(text) {
		return "ja"
	}
	if r.hasChineseCharacters(text) {
		return "zh"
	}
	if r.hasKoreanCharacters(text) {
		return "ko"
	}
	if r.hasArabicCharacters(text) {
		return "ar"
	}

	// Default to English for Latin scripts
	return "en"
}

// stripHTMLTags removes HTML tags from content
func (r *Resolver) stripHTMLTags(content string) string {
	// Simple HTML tag removal - replace with regex for production
	htmlTag := regexp.MustCompile(`<[^>]*>`)
	return htmlTag.ReplaceAllString(content, "")
}

// hasJapaneseCharacters checks for Japanese characters
func (r *Resolver) hasJapaneseCharacters(text string) bool {
	for _, r := range text {
		if (r >= 0x3040 && r <= 0x309F) || // Hiragana
			(r >= 0x30A0 && r <= 0x30FF) || // Katakana
			(r >= 0x4E00 && r <= 0x9FAF) { // CJK Ideographs (includes Kanji)
			return true
		}
	}
	return false
}

// hasChineseCharacters checks for Chinese characters
func (r *Resolver) hasChineseCharacters(text string) bool {
	for _, r := range text {
		if (r >= 0x4E00 && r <= 0x9FAF) || // CJK Ideographs
			(r >= 0x3400 && r <= 0x4DBF) { // CJK Extension A
			return true
		}
	}
	return false
}

// hasKoreanCharacters checks for Korean characters
func (r *Resolver) hasKoreanCharacters(text string) bool {
	for _, r := range text {
		if r >= 0xAC00 && r <= 0xD7AF { // Hangul Syllables
			return true
		}
	}
	return false
}

// hasArabicCharacters checks for Arabic characters
func (r *Resolver) hasArabicCharacters(text string) bool {
	for _, r := range text {
		if r >= 0x0600 && r <= 0x06FF { // Arabic
			return true
		}
	}
	return false
}

// extractMentionsFromNote extracts mention objects from ActivityPub note tags
func (r *Resolver) extractMentionsFromNote(note *activitypub.Note) []*model.Mention {
	if note == nil || len(note.Tag) == 0 {
		return []*model.Mention{}
	}

	mentions := []*model.Mention{}

	for _, tag := range note.Tag {
		if tag.Type == "Mention" && tag.Href != "" {
			// Extract username and domain from mention URL
			username, domain := r.parseMentionURL(tag.Href)
			if username != "" {
				mentions = append(mentions, &model.Mention{
					ID:       tag.Href,
					Username: username,
					Domain:   domain,
					URL:      tag.Href,
				})
			}
		}
	}

	return mentions
}

// parseMentionURL extracts username and domain from a mention URL
func (r *Resolver) parseMentionURL(url string) (username string, domain *string) {
	if err := common.ValidateRequiredParam("url", url); err != nil {
		return "", nil
	}

	// Parse the URL to extract components
	// Expected formats: https://domain.com/users/username or https://domain.com/@username
	parts := strings.Split(url, "/")
	if len(parts) < 3 {
		return "", nil
	}

	// Extract domain
	domainPart := parts[2] // e.g., "example.com"

	// Extract username (last part of URL, removing @ if present)
	usernamePart := parts[len(parts)-1]
	usernamePart = strings.TrimPrefix(usernamePart, "@")

	if err := common.ValidateRequiredParam("usernamePart", usernamePart); err != nil {
		return "", nil
	}

	// Return domain only if it's different from current instance
	var domainPtr *string
	if domainPart != "" && !strings.Contains(r.Registry.GetConfig().BaseURL, domainPart) {
		domainPtr = &domainPart
	}

	return usernamePart, domainPtr
}

func (r *Resolver) convertStatusToObject(ctx context.Context, status *models.Status) *model.Object {
	if status == nil {
		return nil
	}

	objectType := model.ObjectTypeNote

	visibility := model.VisibilityPublic
	switch status.Visibility {
	case VisibilityUnlisted:
		visibility = model.VisibilityUnlisted
	case VisibilityPrivate, EventTypeFollowers:
		visibility = model.VisibilityFollowers
	case TimelineTypeDirect:
		visibility = model.VisibilityDirect
	}

	var actor *activitypub.Actor
	if status.AuthorUsername != "" {
		result, err := r.Registry.Accounts().GetAccount(ctx, status.AuthorUsername)
		if err == nil && result != nil {
			actor = r.convertAccountToActor(result)
		}
	}

	attachments := make([]*activitypub.Attachment, 0)
	if status.Note != nil {
		for _, att := range status.Note.Attachment {
			attachments = append(attachments, &att)
		}
	}

	tags := make([]*activitypub.Tag, 0)
	if status.Note != nil {
		for _, tag := range status.Note.Tag {
			tags = append(tags, &tag)
		}
	}

	mentions := make([]*model.Mention, 0)
	if status.Mentions != nil {
		for _, mentionURL := range status.Mentions {
			// Enhanced: use improved URL parsing with domain detection
			username, domain := r.parseMentionURL(mentionURL)
			if username != "" {
				mentions = append(mentions, &model.Mention{
					ID:       mentionURL,
					Username: username,
					URL:      mentionURL,
					Domain:   domain,
				})
			}
		}
	}

	var inReplyTo *model.Object
	// Fetch parent status if this is a reply (with depth limiting to avoid infinite recursion)
	if status.InReplyToID != "" {
		// Check context for conversion depth to prevent infinite loops
		depth := r.getConversionDepth(ctx)
		if depth < 3 { // Limit to 3 levels of nesting
			newCtx := r.setConversionDepth(ctx, depth+1)
			parentStatus, err := r.Registry.Notes().GetNote(newCtx, status.InReplyToID)
			if err == nil && parentStatus != nil {
				inReplyTo = r.convertStatusToObject(newCtx, parentStatus)
			}
		}
	}

	var summary *string
	if status.Note != nil && status.Note.Summary != "" {
		summary = &status.Note.Summary
	}

	obj := &model.Object{
		ID:               status.StatusID,
		Type:             objectType,
		Actor:            actor,
		Content:          status.Content,
		ContentMap:       r.extractContentMaps(status.Content), // Enhanced: extract content maps with language detection
		InReplyTo:        inReplyTo,
		Visibility:       visibility,
		Sensitive:        status.Sensitive,
		SpoilerText:      summary,
		Attachments:      attachments,
		Tags:             tags,
		Mentions:         mentions,
		CreatedAt:        model.Time(status.CreatedAt),
		UpdatedAt:        model.Time(status.UpdatedAt),
		RepliesCount:     status.ReplyCount,
		LikesCount:       status.LikeCount,
		SharesCount:      status.ReblogCount,
		CommunityNotes:   []*model.CommunityNote{},
		Quoteable:        true,
		QuotePermissions: model.QuotePermissionEveryone,
		QuoteCount:       0,
		EstimatedCost:    1,
	}

	return obj
}

// Helper functions for managing conversion depth to prevent infinite recursion
type conversionDepthKey struct{}

func (r *Resolver) getConversionDepth(ctx context.Context) int {
	if depth, ok := ctx.Value(conversionDepthKey{}).(int); ok {
		return depth
	}
	return 0
}

func (r *Resolver) setConversionDepth(ctx context.Context, depth int) context.Context {
	return context.WithValue(ctx, conversionDepthKey{}, depth)
}

// ModerationFilter extension helpers for proper field resolution
// This provides a thread-safe way to extend GraphQL objects with additional fields
var moderationFilterExtensions = struct {
	sync.RWMutex
	data map[string]map[string]interface{}
}{
	data: make(map[string]map[string]interface{}),
}

func (r *Resolver) setModerationFilterExtension(_ context.Context, obj *moderation.ModerationFilter, field string, value interface{}) {
	objectID := fmt.Sprintf("%p", obj) // Use pointer address as unique identifier

	moderationFilterExtensions.Lock()
	defer moderationFilterExtensions.Unlock()

	if moderationFilterExtensions.data[objectID] == nil {
		moderationFilterExtensions.data[objectID] = make(map[string]interface{})
	}
	moderationFilterExtensions.data[objectID][field] = value
}

// fetchActorFromStorage attempts to fetch an actor from storage repositories
func (r *Resolver) fetchActorFromStorage(ctx context.Context, actorID string) *activitypub.Actor {
	if err := common.ValidateRequiredParam("actorID", actorID); err != nil {
		return nil
	}

	// Try to fetch from accounts first (for local accounts)
	if account, err := r.Registry.Accounts().GetAccount(ctx, actorID); err == nil && account != nil {
		return r.convertAccountToActor(account)
	}

	// Try to fetch from actors repository (for remote actors)
	storage := r.Storage
	if storage != nil {
		if actor, err := storage.Actor().GetActor(ctx, actorID); err == nil && actor != nil {
			return &activitypub.Actor{
				BaseObject: activitypub.BaseObject{
					ID:   actor.ID,
					Type: actor.Type,
				},
				PreferredUsername: actor.PreferredUsername,
				Name:              actor.Name,
				Summary:           actor.Summary,
				Inbox:             actor.Inbox,
				Outbox:            actor.Outbox,
				Followers:         actor.Followers,
				Following:         actor.Following,
				Icon:              actor.Icon,
				Image:             actor.Image,
				PublicKey:         actor.PublicKey,
			}
		}
	}

	// If not found, return a minimal actor with proper domain-based URL structure
	domain := r.Registry.GetConfig().BaseURL
	if err := common.ValidateRequiredParam("domain", domain); err != nil {
		domain = "https://localhost"
	}

	return &activitypub.Actor{
		BaseObject: activitypub.BaseObject{
			ID:   fmt.Sprintf("%s/users/%s", domain, actorID),
			Type: "Person",
		},
		PreferredUsername: actorID,
		Inbox:             fmt.Sprintf("%s/users/%s/inbox", domain, actorID),
		Outbox:            fmt.Sprintf("%s/users/%s/outbox", domain, actorID),
	}
}

func (r *Resolver) convertSuggestionSource(source string) model.SuggestionSource {
	switch strings.ToUpper(source) {
	case "STAFF":
		return model.SuggestionSourceStaff
	case "PAST_INTERACTIONS":
		return model.SuggestionSourcePastInteractions
	case "SIMILAR_PROFILES":
		return model.SuggestionSourceSimilarProfiles
	default:
		return model.SuggestionSourceGlobal
	}
}

