// The following resolvers implement advanced features like trust graphs,
// moderation patterns, and community analytics

// TrustGraph is the resolver for the trustGraph field.
func (r *queryResolver) TrustGraph(ctx context.Context, actorID string, category *models.TrustCategory) ([]*trust.TrustEdge, error) {
	_, err := r.requireAuth(ctx)
	if err != nil {
		return nil, err
	}

	r.Logger.Info("Fetching trust graph",
		zap.String("actor", actorID),
		zap.String("category", func() string {
			if category != nil {
				return string(*category)
			}
			return "all"
		}()))

	// Validate inputs
	if err := common.ValidateRequiredParam("actorID", actorID); err != nil {
		return nil, ErrActorIDRequired
	}

	trustRepo := r.Registry.GetStorage().Trust()

	// Get relationships where this actor is trusted (incoming trust)
	incomingRels, _, err := trustRepo.GetTrustedByRelationships(ctx, actorID, 100, "")
	if err != nil && err != storage.ErrNotFound {
		r.Logger.Error("Failed to get incoming trust relationships", zap.Error(err))
		return nil, errors.Join(errors.New("failed to fetch trust relationships"), err)
	}

	// Get relationships where this actor trusts others (outgoing trust)
	outgoingRels, _, err := trustRepo.GetTrustRelationships(ctx, actorID, 100, "")
	if err != nil && err != storage.ErrNotFound {
		r.Logger.Error("Failed to get outgoing trust relationships", zap.Error(err))
		return nil, errors.Join(errors.New("failed to fetch trust relationships"), err)
	}

	// Combine all relationships
	allRels := append(incomingRels, outgoingRels...)

	// Filter by category if specified
	filteredRels := allRels
	if category != nil {
		filteredRels = make([]*storage.TrustRelationship, 0)
		for _, rel := range allRels {
			if rel.Category == storage.TrustCategory(*category) {
				filteredRels = append(filteredRels, rel)
			}
		}
	}

	// Convert to TrustEdge objects
	edges := make([]*trust.TrustEdge, 0, len(filteredRels))
	for _, rel := range filteredRels {
		edge := &trust.TrustEdge{
			From:       rel.TrusterID,
			To:         rel.TrusteeID,
			Category:   rel.Category,
			Score:      rel.Score,
			Confidence: rel.Confidence,
			Weight:     rel.Score * rel.Confidence,
		}
		edges = append(edges, edge)
	}

	r.Logger.Info("Trust graph fetched successfully",
		zap.String("actor", actorID),
		zap.Int("edge_count", len(edges)))

	return edges, nil
}

// ModerationQueue is the resolver for the moderationQueue field.
func (r *queryResolver) ModerationQueue(ctx context.Context, first *int, after *model.Cursor) ([]*moderation.ModerationDecision, error) {
	// Get moderation repository from service registry
	moderationRepo := r.Registry.GetStorage().Moderation()
	if moderationRepo == nil {
		return nil, ErrModerationUnavailable
	}

	// Set default limit and extract cursor
	limit := 20
	if first != nil && *first > 0 {
		limit = *first
		// Cap at reasonable maximum
		if limit > 100 {
			limit = 100
		}
	}

	var cursor string
	if after != nil {
		cursor = string(*after)
	}

	// Get moderation queue items from repository
	queueItems, _, err := moderationRepo.GetModerationQueuePaginated(ctx, limit, cursor)
	if err != nil {
		r.Logger.Error("Failed to get moderation queue", zap.Error(err))
		return nil, errors.Join(errors.New("failed to retrieve moderation queue"), err)
	}

	// Convert storage.ModerationQueueItem to moderation.ModerationDecision
	decisions := make([]*moderation.ModerationDecision, 0, len(queueItems))
	for _, item := range queueItems {
		if item.Event == nil {
			continue // Skip items without events
		}

		// Create moderation decision from queue item and event
		decision := &moderation.ModerationDecision{
			ID:            item.ID,
			EventID:       item.Event.ID,
			ObjectID:      item.Event.ObjectID,
			Action:        moderation.ActionTypeNone, // Default action for pending items
			ReviewerCount: item.ReviewCount,
			Reviews:       []*moderation.Review{}, // Empty for queue items
			Decided:       item.CreatedAt,
		}

		// Set reason from event or item
		if item.Reason != "" {
			decision.Reason = item.Reason
		} else if item.Event.Reason != "" {
			decision.Reason = item.Event.Reason
		}

		decisions = append(decisions, decision)
	}

	r.Logger.Debug("Retrieved moderation queue",
		zap.Int("requested_limit", limit),
		zap.Int("returned_count", len(decisions)),
		zap.String("cursor", cursor))

	return decisions, nil
}

// ExplainObject is the resolver for the explainObject field.
func (r *queryResolver) ExplainObject(ctx context.Context, id string) (*model.ObjectExplanation, error) {
	// Get object repository from storage
	objectRepo := r.Registry.GetStorage().Object()
	if objectRepo == nil {
		return nil, ErrObjectRepositoryUnavailable
	}

	// Retrieve the object from storage
	obj, err := objectRepo.GetObject(ctx, id)
	if err != nil {
		r.Logger.Error("failed to get object for explanation",
			zap.String("object_id", id),
			zap.Error(err))
		return nil, errors.Join(errors.New("object not found"), err)
	}

	// Convert to GraphQL model object
	modelObject := r.convertObjectToModel(obj)
	if modelObject == nil {
		return nil, ErrUnableToConvertObject
	}

	// Get AI service for content analysis
	aiSvc := r.Registry.AI()
	var explanation *model.ObjectExplanation

	if aiSvc != nil {
		// AI-powered analysis
		explanation = r.generateAIExplanation(ctx, aiSvc, id, modelObject, obj)
	} else {
		// Fallback to basic structural analysis
		explanation = r.generateFallbackExplanation(id, modelObject, obj)
	}

	// Calculate storage cost and access patterns
	r.enrichWithStorageAnalysis(ctx, explanation, id)

	r.Logger.Debug("Generated object explanation",
		zap.String("object_id", id),
		zap.String("object_type", string(modelObject.Type)),
		zap.Int("size_bytes", explanation.SizeBytes),
		zap.Float64("storage_cost", explanation.StorageCost))

	return explanation, nil
}

// convertObjectToModel converts an ActivityPub object to GraphQL model object
func (r *queryResolver) convertObjectToModel(obj any) *model.Object {
	switch o := obj.(type) {
	case *activitypub.Note:
		return &model.Object{
			ID:         o.ID,
			Type:       model.ObjectTypeNote,
			Content:    o.Content,
			CreatedAt:  model.Time(*o.Published),
			UpdatedAt:  model.Time(time.Now()),
			Sensitive:  o.Sensitive,
			Visibility: r.mapActivityPubVisibility(o.Visibility),
		}
	case *activitypub.Article:
		return &model.Object{
			ID:        o.ID,
			Type:      model.ObjectTypeArticle,
			Content:   o.Content,
			CreatedAt: model.Time(*o.Published),
			UpdatedAt: model.Time(time.Now()),
		}
	case map[string]interface{}:
		// Handle generic ActivityPub objects stored as maps
		if objType, ok := o["type"].(string); ok {
			modelObj := &model.Object{
				ID:        getStringFromMap(o, "id"),
				Content:   getStringFromMap(o, "content"),
				CreatedAt: model.Time(time.Now()),
				UpdatedAt: model.Time(time.Now()),
			}

			// Map ActivityPub types to GraphQL types
			switch strings.ToLower(objType) {
			case ContentTypeNote:
				modelObj.Type = model.ObjectTypeNote
			case "article":
				modelObj.Type = model.ObjectTypeArticle
			case "image":
				modelObj.Type = model.ObjectTypeImage
			case "video":
				modelObj.Type = model.ObjectTypeVideo
			default:
				modelObj.Type = model.ObjectTypeNote // Default fallback
			}

			return modelObj
		}
	}
	return nil
}

// generateAIExplanation creates an AI-powered explanation of the object
func (r *queryResolver) generateAIExplanation(ctx context.Context, aiSvc *aiService.Service, objectID string, modelObject *model.Object, obj any) *model.ObjectExplanation {
	// Try to get existing AI analysis
	if result, err := aiSvc.GetAnalysis(ctx, &aiService.GetAnalysisQuery{ObjectID: objectID}); err == nil && result.Analysis != nil {
		analysis := result.Analysis

		// Create explanation with AI insights
		explanation := &model.ObjectExplanation{
			Object:          modelObject,
			StorageLocation: fmt.Sprintf("DynamoDB Table: main, PK: object#%s, SK: object#%s", objectID, objectID),
			SizeBytes:       r.calculateObjectSize(obj),
			StorageCost:     r.estimateStorageCost(obj),
			AccessPattern:   []*model.AccessLog{},
		}

		// Add AI analysis access log
		explanation.AccessPattern = append(explanation.AccessPattern, &model.AccessLog{
			Timestamp: model.Time(analysis.AnalyzedAt),
			Operation: "AI_Analysis",
			Cost:      5, // Estimated cost for AI analysis
		})

		return explanation
	}

	// Queue for AI analysis if not available
	if _, err := aiSvc.QueueForAnalysis(ctx, &aiService.QueueAnalysisCommand{
		ObjectID:   objectID,
		ObjectType: string(modelObject.Type),
		Force:      false,
	}); err != nil {
		r.Logger.Warn("failed to queue object for AI analysis",
			zap.String("object_id", objectID),
			zap.Error(err))
	}

	// Generate explanation with note about pending AI analysis
	return r.generateFallbackExplanation(objectID, modelObject, obj)
}

// generateFallbackExplanation creates a structural analysis when AI is unavailable
func (r *queryResolver) generateFallbackExplanation(objectID string, modelObject *model.Object, obj any) *model.ObjectExplanation {
	explanation := &model.ObjectExplanation{
		Object:          modelObject,
		StorageLocation: fmt.Sprintf("DynamoDB Table: main, PK: object#%s, SK: object#%s", objectID, objectID),
		SizeBytes:       r.calculateObjectSize(obj),
		StorageCost:     r.estimateStorageCost(obj),
		AccessPattern:   []*model.AccessLog{},
	}

	return explanation
}

// enrichWithStorageAnalysis adds storage cost and access pattern information
func (r *queryResolver) enrichWithStorageAnalysis(ctx context.Context, explanation *model.ObjectExplanation, objectID string) {
	// Get cost tracking repository for real cost data
	costRepo := r.Registry.GetStorage().Cost()
	if costRepo != nil {
		if activityCost, err := costRepo.GetActivityCost(ctx, objectID); err == nil && activityCost != nil {
			// Use real cost data if available (TotalCostMicroCents converted to dollars)
			explanation.StorageCost = float64(activityCost.TotalCostMicroCents) / 1000000.0

			// Add access logs from cost tracking
			explanation.AccessPattern = append(explanation.AccessPattern, &model.AccessLog{
				Timestamp: model.Time(activityCost.Timestamp),
				Operation: "GetItem",
				Cost:      int(activityCost.ReadCapacityUnits),
			})
		}
	}

	// Add synthetic access pattern for demonstration
	if err := common.ValidateSliceNotEmpty("access_pattern", explanation.AccessPattern); err != nil {
		explanation.AccessPattern = []*model.AccessLog{
			{
				Timestamp: model.Time(time.Now().Add(-time.Hour)),
				Operation: "GetItem",
				Cost:      1,
			},
			{
				Timestamp: model.Time(time.Now().Add(-30 * time.Minute)),
				Operation: "Query",
				Cost:      2,
			},
		}
	}
}

// calculateObjectSize estimates the storage size of an object in bytes
func (r *queryResolver) calculateObjectSize(obj any) int {
	switch o := obj.(type) {
	case *activitypub.Note:
		size := len(o.ID) + len(o.Content) + len(o.Type)
		if o.Summary != "" {
			size += len(o.Summary)
		}
		// Add estimated overhead for DynamoDB storage
		return size + 100 // Base overhead for keys and metadata
	case *activitypub.Article:
		size := len(o.ID) + len(o.Content) + len(o.Type)
		if o.Name != "" {
			size += len(o.Name)
		}
		return size + 100
	case map[string]interface{}:
		// Estimate size based on JSON representation
		if jsonBytes, err := json.Marshal(obj); err == nil {
			return len(jsonBytes) + 100 // Add DynamoDB overhead
		}
		return 500 // Default estimate
	default:
		return 300 // Conservative default
	}
}

// estimateStorageCost calculates the estimated monthly storage cost
func (r *queryResolver) estimateStorageCost(obj any) float64 {
	sizeBytes := float64(r.calculateObjectSize(obj))
	// DynamoDB storage cost: $0.25 per GB per month
	// Convert bytes to GB and calculate monthly cost
	sizeGB := sizeBytes / (1024 * 1024 * 1024)
	return sizeGB * 0.25
}

// calculateDetailedFederationCostBreakdown calculates detailed cost breakdown with data transfer
func (r *queryResolver) calculateDetailedFederationCostBreakdown(fedCost *models.FederationCost) *model.CostBreakdown {
	// Calculate individual service costs using the cost tracker constants and formulas

	// Data Transfer Costs - Calculate from actual ingress/egress bytes
	totalTransferBytes := fedCost.IngressBytes + fedCost.EgressBytes
	transferGB := float64(totalTransferBytes) / (1024 * 1024 * 1024)
	dataTransferCost := transferGB * 0.09 // $0.09 per GB data transfer out (S3DataTransferPerGB constant converted to dollars)

	// DynamoDB Costs - Estimate based on request count and typical read/write ratio
	// Assume 70% reads, 30% writes for federation activities
	reads := int64(float64(fedCost.RequestCount) * 0.7)
	writes := int64(float64(fedCost.RequestCount) * 0.3)
	dynamoDBCost := float64(reads*25+writes*125) / 1000000.0 // Convert from microcents to dollars

	// Lambda Costs - Estimate based on request count and typical Lambda execution
	// Assume average 200ms execution time and 512MB memory per federation request
	lambdaInvocations := fedCost.RequestCount
	avgDurationMs := int64(200)
	avgMemoryMB := int64(512)
	lambdaRequestCost := float64(lambdaInvocations*20) / 1000000.0 // Request cost using cost.LambdaRequestCost
	gbSeconds := float64(avgDurationMs*avgMemoryMB*lambdaInvocations) / (1000 * 1024)
	lambdaComputeCost := gbSeconds * 0.0000166667 // GB-second cost using cost.LambdaGBSecondCost
	lambdaCost := lambdaRequestCost + lambdaComputeCost

	// S3 Storage Costs - Minimal for federation (mostly metadata)
	// Estimate based on request count and average object sizes
	estimatedS3Gets := fedCost.RequestCount / 2                                     // Assume half are GET operations
	estimatedS3Puts := fedCost.RequestCount / 10                                    // Assume 10% are PUT operations
	s3Cost := float64(estimatedS3Gets*40/1000+estimatedS3Puts*500/1000) / 1000000.0 // Using cost tracker constants

	// Total cost calculation
	totalCost := dataTransferCost + dynamoDBCost + lambdaCost + s3Cost

	// Create detailed breakdown items
	breakdownItems := []*model.CostItem{}

	if dynamoDBCost > 0 {
		breakdownItems = append(breakdownItems, &model.CostItem{
			Operation: "DynamoDB Operations",
			Count:     int(reads + writes),
			Cost:      dynamoDBCost,
		})
	}

	if lambdaCost > 0 {
		breakdownItems = append(breakdownItems, &model.CostItem{
			Operation: "Lambda Execution",
			Count:     int(lambdaInvocations),
			Cost:      lambdaCost,
		})
	}

	if s3Cost > 0 {
		breakdownItems = append(breakdownItems, &model.CostItem{
			Operation: "S3 Operations",
			Count:     int(estimatedS3Gets + estimatedS3Puts),
			Cost:      s3Cost,
		})
	}

	if dataTransferCost > 0 {
		breakdownItems = append(breakdownItems, &model.CostItem{
			Operation: "Data Transfer",
			Count:     int(totalTransferBytes / (1024 * 1024)), // Count in MB
			Cost:      dataTransferCost,
		})
	}

	return &model.CostBreakdown{
		Period:           model.PeriodMonth,
		TotalCost:        totalCost,
		DynamoDBCost:     dynamoDBCost,
		S3StorageCost:    s3Cost,
		LambdaCost:       lambdaCost,
		DataTransferCost: dataTransferCost,
		Breakdown:        breakdownItems,
	}
}

// mapActivityPubVisibility maps ActivityPub visibility to GraphQL visibility
func (r *queryResolver) mapActivityPubVisibility(visibility string) model.Visibility {
	switch strings.ToLower(visibility) {
	case StreamNamePublic:
		return model.VisibilityPublic
	case VisibilityUnlisted:
		return model.VisibilityUnlisted
	case VisibilityPrivate, EventTypeFollowers:
		return model.VisibilityFollowers
	case TimelineTypeDirect:
		return model.VisibilityDirect
	default:
		return model.VisibilityPublic // Default fallback
	}
}

// getStringFromMap safely extracts a string value from a map
func getStringFromMap(m map[string]interface{}, key string) string {
	if val, ok := m[key]; ok {
		if str, ok := val.(string); ok {
			return str
		}
	}
	return ""
}

// FederationStatus is the resolver for the federationStatus field.
func (r *queryResolver) FederationStatus(ctx context.Context, domain string) (*model.FederationStatus, error) {
	// Get federation repository for metrics and analytics
	federationRepo := r.Registry.GetStorage().Federation()
	if federationRepo == nil {
		return nil, ErrFederationRepositoryUnavailable
	}

	// Initialize the federation status response
	status := &model.FederationStatus{
		Domain:    domain,
		Reachable: false,
	}

	// Get health score and recent metrics
	healthScore := r.getDomainHealthScore(ctx, federationRepo, domain)
	recentMetrics := r.getRecentFederationMetrics(ctx, federationRepo, domain)

	// Determine reachability from recent metrics
	r.determineReachabilityFromMetrics(status, recentMetrics)

	// Get and apply instance information
	instanceInfo := r.getInstanceInfo(ctx, federationRepo, domain)
	r.applyInstanceInfoToStatus(status, instanceInfo)

	// Handle case where no instance information is available
	r.handleMissingInstanceInfo(status, instanceInfo, domain)

	r.Logger.Debug("federation status resolved",
		zap.String("domain", domain),
		zap.Bool("reachable", status.Reachable),
		zap.Float64("health_score", healthScore),
		zap.Int("recent_metrics_count", len(recentMetrics)),
		zap.Bool("has_instance_info", instanceInfo != nil))

	return status, nil
}

// getDomainHealthScore retrieves the health score for a domain
func (r *queryResolver) getDomainHealthScore(ctx context.Context, federationRepo interface{}, domain string) float64 {
	repo := federationRepo.(interface {
		GetDomainHealthScore(context.Context, string) (float64, error)
	})
	healthScore, err := repo.GetDomainHealthScore(ctx, domain)
	if err != nil {
		r.Logger.Debug("no health score found for domain",
			zap.String("domain", domain),
			zap.Error(err))
		return 0.0
	}
	return healthScore
}

// getRecentFederationMetrics retrieves recent federation metrics for a domain
func (r *queryResolver) getRecentFederationMetrics(ctx context.Context, federationRepo interface{}, domain string) []*models.FederationAnalyticsTimeSeries {
	repo := federationRepo.(interface {
		GetDetailedMetricsByPeriod(context.Context, string, time.Time, time.Time, int) ([]*models.FederationAnalyticsTimeSeries, error)
	})
	endTime := time.Now()
	startTime := endTime.Add(-30 * time.Minute) // Last 30 minutes of activity

	recentMetrics, err := repo.GetDetailedMetricsByPeriod(ctx, "5min", startTime, endTime, 10)
	if err != nil {
		r.Logger.Debug("no recent metrics found for domain",
			zap.String("domain", domain),
			zap.Error(err))
		return []*models.FederationAnalyticsTimeSeries{}
	}
	return recentMetrics
}

// determineReachabilityFromMetrics analyzes recent metrics to determine domain reachability
func (r *queryResolver) determineReachabilityFromMetrics(status *model.FederationStatus, recentMetrics []*models.FederationAnalyticsTimeSeries) {
	if err := common.ValidateSliceNotEmpty("recent_metrics", recentMetrics); err != nil {
		return
	}

	// Check for successful contact in recent metrics
	if r.findSuccessfulContact(status, recentMetrics) {
		return
	}

	// If no successful contact, check for any recent activity
	r.findRecentActivity(status, recentMetrics)
}

// findSuccessfulContact looks for metrics with successful contact
func (r *queryResolver) findSuccessfulContact(status *model.FederationStatus, recentMetrics []*models.FederationAnalyticsTimeSeries) bool {
	for _, metric := range recentMetrics {
		if metric.LastSuccessfulContact != nil {
			status.Reachable = true
			status.LastContact = (*model.Time)(metric.LastSuccessfulContact)
			return true
		}
	}
	return false
}

// findRecentActivity looks for any recent activity indicators
func (r *queryResolver) findRecentActivity(status *model.FederationStatus, recentMetrics []*models.FederationAnalyticsTimeSeries) {
	for _, metric := range recentMetrics {
		if metric.ActivityCount > 0 && metric.InstanceReachability > 0 {
			status.Reachable = true
			status.LastContact = (*model.Time)(&metric.Timestamp)
			return
		}
	}
}

// getInstanceInfo retrieves cached instance information for a domain
func (r *queryResolver) getInstanceInfo(ctx context.Context, federationRepo interface{}, domain string) *models.FederationInstance {
	repo := federationRepo.(interface {
		GetInstanceInfo(context.Context, string) (*models.FederationInstance, error)
	})
	instanceInfo, err := repo.GetInstanceInfo(ctx, domain)
	if err != nil {
		r.Logger.Debug("could not get instance information",
			zap.String("domain", domain),
			zap.Error(err))
		return nil
	}
	return instanceInfo
}

// applyInstanceInfoToStatus populates status fields from instance information
func (r *queryResolver) applyInstanceInfoToStatus(status *model.FederationStatus, instanceInfo *models.FederationInstance) {
	if instanceInfo == nil {
		return
	}

	// Set instance-level information if available
	if instanceInfo.SharedInbox != "" {
		status.SharedInbox = &instanceInfo.SharedInbox
	}
	if instanceInfo.PublicKey != "" {
		status.PublicKey = &instanceInfo.PublicKey
	}
	if instanceInfo.Software != "" {
		status.Software = &instanceInfo.Software
	}
	if instanceInfo.Version != "" {
		status.Version = &instanceInfo.Version
	}

	// Check reachability based on last seen if not already determined
	r.checkReachabilityFromLastSeen(status, instanceInfo)
}

// checkReachabilityFromLastSeen updates reachability based on instance last seen time
func (r *queryResolver) checkReachabilityFromLastSeen(status *model.FederationStatus, instanceInfo *models.FederationInstance) {
	if status.Reachable || instanceInfo.LastSeen.IsZero() {
		return
	}

	// Check if last seen was reasonably recent (within 24 hours)
	if time.Since(instanceInfo.LastSeen) < 24*time.Hour {
		status.Reachable = true
		status.LastContact = (*model.Time)(&instanceInfo.LastSeen)
	}
}

// handleMissingInstanceInfo handles the case when no instance information is available
func (r *queryResolver) handleMissingInstanceInfo(status *model.FederationStatus, instanceInfo *models.FederationInstance, domain string) {
	if instanceInfo != nil {
		return
	}

	r.Logger.Debug("no cached instance information available",
		zap.String("domain", domain))

	// For GraphQL queries, we don't want to trigger expensive network operations
	// Conservative approach: assume not reachable if no cached data
	if domain != "" {
		status.Reachable = false
	}
}

// AIAnalysis is the resolver for the aiAnalysis field.
func (r *queryResolver) AiAnalysis(ctx context.Context, objectID string) (*model.AIAnalysis, error) {
	// Get AI service from registry
	aiSvc := r.Registry.AI()
	if aiSvc == nil {
		return nil, ErrAIServiceUnavailable
	}

	// Retrieve analysis from storage
	result, err := aiSvc.GetAnalysis(ctx, &aiService.GetAnalysisQuery{
		ObjectID: objectID,
	})
	if err != nil {
		return nil, errors.Join(errors.New("failed to get AI analysis"), err)
	}

	if result.Analysis == nil {
		return nil, nil // No analysis found
	}

	analysis := result.Analysis

	// Convert to GraphQL model
	return &model.AIAnalysis{
		ID:               analysis.ID,
		ObjectID:         analysis.ObjectID,
		ObjectType:       analysis.ObjectType,
		OverallRisk:      analysis.OverallRisk,
		Confidence:       analysis.Confidence,
		ModerationAction: r.convertModerationAction(analysis.ModerationAction),
		AnalyzedAt:       model.Time(analysis.AnalyzedAt),
		TextAnalysis:     r.convertTextAnalysisToModeration(analysis.TextAnalysis),
		ImageAnalysis:    r.convertImageAnalysisToModeration(analysis.ImageAnalysis),
		SpamAnalysis:     r.convertSpamAnalysis(analysis.SpamAnalysis),
		AiDetection:      r.convertAIDetection(analysis.AIDetection),
	}, nil
}

// AIStats is the resolver for the aiStats field.
func (r *queryResolver) AiStats(ctx context.Context, period model.Period) (*model.AIStats, error) {
	username, err := r.requireAuth(ctx)
	if err != nil {
		return nil, err
	}

	// Get AI service if available
	aiSvc := r.Registry.AI()
	if aiSvc == nil {
		// Return zeros if AI service not available
		return &model.AIStats{
			Period:        string(period),
			TotalAnalyses: 0,
			ToxicContent:  0,
			SpamDetected:  0,
			AiGenerated:   0,
			NsfwContent:   0,
			PiiDetected:   0,
			ToxicityRate:  0,
			SpamRate:      0,
			AiContentRate: 0,
			NsfwRate:      0,
			ModerationActions: &model.ModerationActionCounts{
				None:      0,
				Flag:      0,
				Hide:      0,
				Remove:    0,
				ShadowBan: 0,
				Review:    0,
			},
		}, nil
	}

	// Query REAL stats from the AI service - NO FAKE DATA
	result, err := aiSvc.GetStats(ctx, &aiService.GetStatsQuery{
		Period: string(period),
	})
	if err != nil {
		r.Logger.Error("failed to get AI stats",
			zap.String("user", username),
			zap.String("period", string(period)),
			zap.Error(err))
		return nil, errors.Join(errors.New("failed to get AI stats"), err)
	}

	// Convert service stats to GraphQL model
	stats, ok := result.Stats.(*ai.AIStats)
	if !ok {
		return nil, ErrUnexpectedStatsType
	}

	// Convert moderation actions map to struct
	moderationActions := &model.ModerationActionCounts{
		None:      stats.ModerationActions[NoneValue],
		Flag:      stats.ModerationActions["flag"],
		Hide:      stats.ModerationActions[ModerationActionHide],
		Remove:    stats.ModerationActions[ModerationActionRemove],
		ShadowBan: stats.ModerationActions["shadowban"],
		Review:    stats.ModerationActions["review"],
	}

	r.Logger.Info("Retrieved REAL AI stats from database",
		zap.String("user", username),
		zap.String("period", string(period)),
		zap.Int("total_analyses", stats.TotalAnalyses))

	return &model.AIStats{
		Period:            stats.Period,
		TotalAnalyses:     stats.TotalAnalyses,
		ToxicContent:      stats.ToxicContent,
		SpamDetected:      stats.SpamDetected,
		AiGenerated:       stats.AIGenerated,
		NsfwContent:       stats.NSFWContent,
		PiiDetected:       stats.PIIDetected,
		ToxicityRate:      stats.ToxicityRate,
		SpamRate:          stats.SpamRate,
		AiContentRate:     stats.AIContentRate,
		NsfwRate:          stats.NSFWRate,
		ModerationActions: moderationActions,
	}, nil
}

