// CreatedAt implements ActorResolver
func (r *actorResolver) CreatedAt(_ context.Context, obj *activitypub.Actor) (*model.Time, error) {
	if obj.Published == nil {
		return nil, nil
	}
	t := model.Time(*obj.Published)
	return &t, nil
}

// UpdatedAt implements ActorResolver
func (r *actorResolver) UpdatedAt(_ context.Context, actor *activitypub.Actor) (*model.Time, error) {
	// Return the actual updated time from the actor if available
	if actor.Updated != nil {
		t := model.Time(*actor.Updated)
		return &t, nil
	}

	// Fallback to creation time if updated time is not set
	if actor.Published != nil {
		t := model.Time(*actor.Published)
		return &t, nil
	}

	// Last fallback to current time if neither is available
	t := model.Time(time.Now())
	return &t, nil
}

// Fields implements ActorResolver
func (r *actorResolver) Fields(_ context.Context, obj *activitypub.Actor) ([]*model.Field, error) {
	if err := common.ValidateSliceNotEmpty("attachment", obj.Attachment); err != nil {
		return []*model.Field{}, nil
	}

	fields := make([]*model.Field, 0)
	for _, attachment := range obj.Attachment {
		if attachment.Type == "PropertyValue" {
			fields = append(fields, &model.Field{
				Name:  attachment.Name,
				Value: attachment.Value,
			})
		}
	}
	return fields, nil
}

// TrustScore implements ActorResolver
func (r *actorResolver) TrustScore(ctx context.Context, obj *activitypub.Actor) (float64, error) {
	// Get trust score from DataLoader for performance
	result, err := LoadTrustScore(ctx, obj.PreferredUsername, string(trust.TrustCategoryGeneral))
	if err != nil {
		r.Logger.Warn("failed to load trust score, returning default",
			zap.String("actor", obj.PreferredUsername),
			zap.Error(err))
		return 0.5, nil
	}

	// Cast the result to float64 (should be a trust score)
	if score, ok := result.(float64); ok {
		return score, nil
	}

	r.Logger.Warn("unexpected trust score type, returning default",
		zap.String("actor", obj.PreferredUsername),
		zap.Any("result", result))
	return 0.5, nil
}

// Reputation implements ActorResolver
func (r *actorResolver) Reputation(ctx context.Context, obj *activitypub.Actor) (*model.Reputation, error) {
	// Get reputation from storage
	storedRep, err := r.Storage.User().GetReputation(ctx, obj.PreferredUsername)
	if err != nil {
		r.Logger.Warn("failed to get stored reputation, calculating new",
			zap.String("actor", obj.PreferredUsername),
			zap.Error(err))
	}

	// If no stored reputation or it's stale, calculate fresh
	var rep *model.Reputation
	if storedRep == nil || time.Since(storedRep.CalculatedAt) > 24*time.Hour {
		rep, err = r.calculateFreshReputation(ctx, obj)
		if err != nil {
			r.Logger.Error("failed to calculate reputation, using default",
				zap.String("actor", obj.PreferredUsername),
				zap.Error(err))
			return r.getDefaultReputation(obj), nil
		}
	} else {
		// Convert stored reputation to GraphQL model
		rep = r.convertStoredReputation(ctx, storedRep, obj)
	}

	// Ensure evidence is populated
	if rep.Evidence == nil {
		rep.Evidence = r.buildReputationEvidence(ctx, obj, storedRep)
	}

	return rep, nil
}

// Vouches implements ActorResolver
func (r *actorResolver) Vouches(ctx context.Context, actor *activitypub.Actor) ([]*model.Vouch, error) {
	if actor == nil || common.ValidateRequiredParam("preferredUsername", actor.PreferredUsername) != nil {
		return []*model.Vouch{}, nil
	}

	// Get trust relationships for this actor (relationships where this actor is trusted by others)
	// This represents vouches from other actors
	trustRepo := r.Storage.Trust()
	if trustRepo == nil {
		r.Logger.Debug("trust repository not available for vouches")
		return []*model.Vouch{}, nil
	}

	// Get relationships where this actor is the trustee (people who vouch for them)
	trustRelationships, _, err := trustRepo.GetTrustedByRelationships(ctx, actor.PreferredUsername, 20, "")
	if err != nil {
		r.Logger.Error("failed to get trust relationships for vouches",
			zap.String("actor", actor.PreferredUsername),
			zap.Error(err))
		return []*model.Vouch{}, nil
	}

	// Convert trust relationships to vouches
	vouches := make([]*model.Vouch, 0, len(trustRelationships))
	for _, trustRel := range trustRelationships {
		if trustRel == nil || trustRel.Score <= 0 {
			continue // Only include positive trust relationships
		}

		// Create a vouch based on the trust relationship
		vouch := &model.Vouch{
			ID:                fmt.Sprintf("%s_vouches_%s", trustRel.TrusterID, trustRel.TrusteeID),
			Confidence:        trustRel.Score,
			Context:           string(trustRel.Category),
			VoucherReputation: 50,                                               // Default reputation score
			CreatedAt:         model.Time(time.Now()),                           // Use current time since CreatedAt not available
			ExpiresAt:         model.Time(time.Now().Add(365 * 24 * time.Hour)), // Expire in 1 year
			Active:            trustRel.Score > 0.5,                             // Consider active if score is above threshold
		}

		// Set From and To actors if possible (would need to fetch actor data)
		// For now, leaving them as nil since we don't have actor conversion here

		vouches = append(vouches, vouch)
	}

	r.Logger.Debug("retrieved vouches for actor",
		zap.String("actor", actor.PreferredUsername),
		zap.Int("vouch_count", len(vouches)))

	return vouches, nil
}

