// ID implements AttachmentResolver
func (r *attachmentResolver) ID(_ context.Context, obj *activitypub.Attachment) (string, error) {
	if obj.URL != "" {
		// Extract media ID from URL using helper function
		if mediaID, err := r.extractMediaIDFromURL(obj.URL); err == nil {
			return mediaID, nil
		}
		// Fallback to full URL if extraction fails
		return obj.URL, nil
	}
	return "", nil
}

// Preview implements AttachmentResolver
func (r *attachmentResolver) Preview(_ context.Context, obj *activitypub.Attachment) (*string, error) {
	// Return URL as preview since Attachment doesn't have PreviewURL field
	if obj.URL != "" {
		return &obj.URL, nil
	}
	return nil, nil
}

// Description implements AttachmentResolver
func (r *attachmentResolver) Description(_ context.Context, obj *activitypub.Attachment) (*string, error) {
	if obj.Name != "" {
		return &obj.Name, nil
	}
	return nil, nil
}

// Blurhash implements AttachmentResolver
func (r *attachmentResolver) Blurhash(ctx context.Context, attachment *activitypub.Attachment) (*string, error) {
	// Get storage from resolver
	storage := r.Storage
	if storage == nil {
		return nil, ErrStorageUnavailable
	}

	// Extract media ID from attachment URL
	mediaID, err := r.extractMediaIDFromURL(attachment.URL)
	if err != nil {
		// If we can't extract media ID, return nil (no blurhash available)
		return nil, nil
	}

	// Get media metadata repository
	metadataRepo := storage.MediaMetadata()
	if metadataRepo == nil {
		return nil, nil
	}

	// Retrieve metadata for the media
	metadata, err := metadataRepo.GetMediaMetadata(ctx, mediaID)
	if err != nil {
		// If metadata not found, return nil (no blurhash available)
		return nil, nil
	}

	// Return blurhash if available
	if metadata.Blurhash != "" {
		return &metadata.Blurhash, nil
	}

	return nil, nil
}

// Duration implements AttachmentResolver
func (r *attachmentResolver) Duration(ctx context.Context, attachment *activitypub.Attachment) (*float64, error) {
	// Get storage from resolver
	storage := r.Storage
	if storage == nil {
		return nil, ErrStorageUnavailable
	}

	// Extract media ID from attachment URL
	mediaID, err := r.extractMediaIDFromURL(attachment.URL)
	if err != nil {
		// If we can't extract media ID, return nil (no duration available)
		return nil, nil
	}

	// Get media metadata repository
	metadataRepo := storage.MediaMetadata()
	if metadataRepo == nil {
		return nil, nil
	}

	// Retrieve metadata for the media
	metadata, err := metadataRepo.GetMediaMetadata(ctx, mediaID)
	if err != nil {
		// If metadata not found, return nil (no duration available)
		return nil, nil
	}

	// Return duration if available and greater than 0
	if metadata.Duration > 0 {
		return &metadata.Duration, nil
	}

	return nil, nil
}

